[
    ExtensionOf(tableStr(WHSContainerTable))
]
final class AVAWHSContainerTableDbt_Extension
{
}

Method.Source:
/// <summary>
/// extension methode for closeContainerUsingParam
/// </summary>
/// <param name = "_closeContainerParams">
/// The close Paramter class WHSCloseContainerParameters
/// </param>
public static void closeContainerUsingParam(WHSCloseContainerParameters _closeContainerParams)
{
    using (AVACloseContainerUsingParamIDisposable instance = AVACloseContainerUsingParamIDisposable::construct())
    {
        instance.closeContainerParams = _closeContainerParams;

        next closeContainerUsingParam(_closeContainerParams);
    }
}

/// <summary>
/// Creates a <c>WHSContainerTable</c> record with given parameters.
/// </summary>
/// <param name="_shipmentId">
/// Shipment id of the record.
/// </param>
/// <param name="_containerId">
/// Container id of the record.
/// </param>
/// <param name="_containerTypeCode">
/// Container type code of the record.
/// </param>
/// <param name="_closeContainerProfileId">
/// Container packing policy id; optional.
/// </param>
/// <param name="_containerGroupingLicensePlateId">
/// Container grouping license plate id; optional.
/// </param>
/// <param name="_containerLocation">
/// Container location; optional.
/// </param>
public static void createContainer(
    WHSShipmentId                       _shipmentId,
    WHSContainerId                      _containerId,
    WHSContainerTypeCode                _containerTypeCode,
    WHSCloseContainerProfileId          _closeContainerProfileId,
    WHSContainerGroupingLicensePlateId  _containerGroupingLicensePlateId,
    WMSLocation							_containerLocation)
{
    AVACreateContainerIDisposable       createContainerIDisposable;

    WHSShipmentId                       shipmentId                      = _shipmentId;
    WHSContainerId                      containerId                     = _containerId;
    WHSContainerTypeCode                containerTypeCode               = _containerTypeCode;
    WHSCloseContainerProfileId          closeContainerProfileId         = _closeContainerProfileId;
    WHSContainerGroupingLicensePlateId  containerGroupingLicensePlateId = _containerGroupingLicensePlateId;
    WMSLocation							containerLocation               = _containerLocation;        

    createContainerIDisposable = AVACreateContainerIDisposable::current();

    if (createContainerIDisposable)
    {
        if (createContainerIDisposable.containerTypeCode)
        {
            containerTypeCode = createContainerIDisposable.containerTypeCode;
        }
    }

    next createContainer(shipmentId,
                         containerId,
                         containerTypeCode,
                         closeContainerProfileId,
                         containerGroupingLicensePlateId,
                         containerLocation);
}

/// <summary>
/// N.Freidenberger
/// </summary>
/// <param name = "_args">_args</param>
/// <param name = "_whsContainerTable">_whsContainerTable</param>
/// <param name = "_showDialog">_showDialog</param>
/// <returns></returns>
protected static MenuFunction createMenuFunctionForPrintingContainerContents(Args _args, WHSContainerTable _whsContainerTable, NoYesId _showDialog)
{
    WHSContainerLine                avaWHSContainerLine;
    WHSCloseContainerProfile        closeContainerProfile = WHSCloseContainerProfile::find(_whsContainerTable.CloseContainerProfileId);


    MenuFunction menuFunction = next createMenuFunctionForPrintingContainerContents(_args,_whsContainerTable,_showDialog);

    select count(RecId) from avaWHSCOntainerLine
                where avaWHSCOntainerLine.ContainerId == _whsContainerTable.ContainerId
                   && avaWHSCOntainerLine.ShipmentId  == _whsContainerTable.ShipmentId;

    if (avaWHSCOntainerLine.RecId < closeContainerProfile.AVAConPosPrint)
    {
        menuFunction = null;
    }

    return menuFunction;
}
